  ('ai:ai-batch-07:13f89c05606c','A1'::public.cefr_level,'reading','When does the swimming pool close?',array['at 9 pm','at 8 pm','at midnight','at 7 am']::text[],'A','''Open every day 7 am – 9 pm.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','SWIMMING POOL. Open every day 7 am – 9 pm. Children under 8 must be with an adult. No food or drinks in the pool area. Please have a shower before you swim.',null,null,null,'practice'),
