  ('ai:ai-batch-07:d6ec9390c44a','A2'::public.cefr_level,'reading','Why did Carlos move to Edinburgh?',array['to study engineering','to join a hiking club','to work in a restaurant','to live with his family']::text[],'A','''...moved from Madrid to Edinburgh to study engineering.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Six months ago Carlos moved from Madrid to Edinburgh to study engineering. At first he found it difficult: the weather was cold and wet, and he didn''t understand the Scottish accent. He also missed his family and Spanish food. But now he has made friends from many countries, and he has joined a hiking club. Last month he climbed Arthur''s Seat, a hill in the middle of the city, and saw the whole of Edinburgh. He says his English has improved a lot because he only speaks English at university.',null,null,null,'practice'),
  ('ai:ai-batch-07:eed4d2e914a3','A2'::public.cefr_level,'reading','What was a problem for Carlos at first?',array['finding a university','making phone calls','the cost of food','understanding the Scottish accent']::text[],'D','''He didn''t understand the Scottish accent.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Six months ago Carlos moved from Madrid to Edinburgh to study engineering. At first he found it difficult: the weather was cold and wet, and he didn''t understand the Scottish accent. He also missed his family and Spanish food. But now he has made friends from many countries, and he has joined a hiking club. Last month he climbed Arthur''s Seat, a hill in the middle of the city, and saw the whole of Edinburgh. He says his English has improved a lot because he only speaks English at university.',null,null,null,'practice'),
  ('ai:ai-batch-07:fbf58ad2eb10','A2'::public.cefr_level,'reading','What did Carlos do last month?',array['went back to Madrid','cooked Spanish food','started university','climbed a hill in the city']::text[],'D','''Last month he climbed Arthur''s Seat.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Six months ago Carlos moved from Madrid to Edinburgh to study engineering. At first he found it difficult: the weather was cold and wet, and he didn''t understand the Scottish accent. He also missed his family and Spanish food. But now he has made friends from many countries, and he has joined a hiking club. Last month he climbed Arthur''s Seat, a hill in the middle of the city, and saw the whole of Edinburgh. He says his English has improved a lot because he only speaks English at university.',null,null,null,'practice'),
  ('ai:ai-batch-07:2fa4faa21cdb','A2'::public.cefr_level,'reading','Why has Carlos''s English improved?',array['He watches English films.','He takes evening classes.','He lives with a Scottish family.','He only speaks English at university.']::text[],'D','''...because he only speaks English at university.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Six months ago Carlos moved from Madrid to Edinburgh to study engineering. At first he found it difficult: the weather was cold and wet, and he didn''t understand the Scottish accent. He also missed his family and Spanish food. But now he has made friends from many countries, and he has joined a hiking club. Last month he climbed Arthur''s Seat, a hill in the middle of the city, and saw the whole of Edinburgh. He says his English has improved a lot because he only speaks English at university.',null,null,null,'practice'),
  ('ai:ai-batch-07:15761112c844','A2'::public.cefr_level,'reading','How does Carlos feel now compared with the beginning?',array['more confused','bored','more homesick','happier and more settled']::text[],'D','He has friends and a club now, unlike at first.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Six months ago Carlos moved from Madrid to Edinburgh to study engineering. At first he found it difficult: the weather was cold and wet, and he didn''t understand the Scottish accent. He also missed his family and Spanish food. But now he has made friends from many countries, and he has joined a hiking club. Last month he climbed Arthur''s Seat, a hill in the middle of the city, and saw the whole of Edinburgh. He says his English has improved a lot because he only speaks English at university.',null,null,null,'practice'),
  ('ai:ai-batch-07:ff522d41af9d','A2'::public.cefr_level,'reading','How many hours a week is the restaurant job?',array['about 18','about 30','about 20','about 11']::text[],'C','''About 20 hours a week.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','WANTED: Part-time waiter or waitress for a busy Italian restaurant in York. Evenings and weekends, about 20 hours a week. No experience needed — we will train you. You must be friendly, polite and over 18. Pay: £11 an hour plus tips. Free meal every shift. Send your CV to jobs@example.com before 30th June.',null,null,null,'practice'),
  ('ai:ai-batch-07:a73912b3c750','A2'::public.cefr_level,'reading','Who can apply for the job?',array['someone over 18 with no experience','only Italians','only people with experience','anyone under 18']::text[],'A','''No experience needed... over 18.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','WANTED: Part-time waiter or waitress for a busy Italian restaurant in York. Evenings and weekends, about 20 hours a week. No experience needed — we will train you. You must be friendly, polite and over 18. Pay: £11 an hour plus tips. Free meal every shift. Send your CV to jobs@example.com before 30th June.',null,null,null,'practice'),
  ('ai:ai-batch-07:abc21ca2fb56','A2'::public.cefr_level,'reading','What do workers get every shift?',array['free Italian lessons','a train ticket','£11 in tips','a free meal']::text[],'D','''Free meal every shift.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','WANTED: Part-time waiter or waitress for a busy Italian restaurant in York. Evenings and weekends, about 20 hours a week. No experience needed — we will train you. You must be friendly, polite and over 18. Pay: £11 an hour plus tips. Free meal every shift. Send your CV to jobs@example.com before 30th June.',null,null,null,'practice'),
  ('ai:ai-batch-07:c5485e362453','A2'::public.cefr_level,'reading','How should you apply?',array['phone the restaurant','visit on a weekend','write a letter','send a CV by email']::text[],'D','''Send your CV to jobs@example.com.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','WANTED: Part-time waiter or waitress for a busy Italian restaurant in York. Evenings and weekends, about 20 hours a week. No experience needed — we will train you. You must be friendly, polite and over 18. Pay: £11 an hour plus tips. Free meal every shift. Send your CV to jobs@example.com before 30th June.',null,null,null,'practice'),
  ('ai:ai-batch-07:c1a208618e88','A2'::public.cefr_level,'reading','When will Lily probably arrive?',array['she can''t come','at about 8.30','at 8','at 7']::text[],'B','''I''ll probably arrive at about 8.30.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Hi Sam, Thanks for inviting me to your party on Saturday. I''d love to come, but I''m afraid I''ll be a bit late. I have to work until 7, and then I need to go home and change. I''ll probably arrive at about 8.30. Is that OK? Shall I bring something? I could make my chocolate cake — everyone liked it last time! See you soon, Lily',null,null,null,'practice'),
  ('ai:ai-batch-07:1cc6516772cc','A2'::public.cefr_level,'reading','Why will Lily be late?',array['Her train is late.','She forgot the time.','She has to make a cake.','She has to work and then change.']::text[],'D','''I have to work until 7, and then I need to go home and change.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Hi Sam, Thanks for inviting me to your party on Saturday. I''d love to come, but I''m afraid I''ll be a bit late. I have to work until 7, and then I need to go home and change. I''ll probably arrive at about 8.30. Is that OK? Shall I bring something? I could make my chocolate cake — everyone liked it last time! See you soon, Lily',null,null,null,'practice'),
  ('ai:ai-batch-07:c05e3e101654','A2'::public.cefr_level,'reading','What does Lily offer to bring?',array['a present for Sam','drinks','music','a chocolate cake']::text[],'D','''I could make my chocolate cake.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Hi Sam, Thanks for inviting me to your party on Saturday. I''d love to come, but I''m afraid I''ll be a bit late. I have to work until 7, and then I need to go home and change. I''ll probably arrive at about 8.30. Is that OK? Shall I bring something? I could make my chocolate cake — everyone liked it last time! See you soon, Lily',null,null,null,'practice'),
  ('ai:ai-batch-07:cdff6ef7d6c4','A2'::public.cefr_level,'reading','How do we know people liked her cake before?',array['She says everyone liked it last time.','She won a prize.','She sells cakes.','Sam asked for it.']::text[],'A','''...everyone liked it last time!''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Hi Sam, Thanks for inviting me to your party on Saturday. I''d love to come, but I''m afraid I''ll be a bit late. I have to work until 7, and then I need to go home and change. I''ll probably arrive at about 8.30. Is that OK? Shall I bring something? I could make my chocolate cake — everyone liked it last time! See you soon, Lily',null,null,null,'practice'),
  ('ai:ai-batch-07:f011390f6eeb','A2'::public.cefr_level,'reading','How much is the gym if you join in January?',array['£20 a year','£10 a month','£30 a month','£20 a month']::text[],'D','''Pay only £20 a month (normal price £30).''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','FitLife Gym — New Year Offer! Join before 31st January and pay only £20 a month (normal price £30). Open 6 am – 10 pm every day. Free fitness classes: yoga on Mondays, dance on Wednesdays, boxing on Fridays. Students get a further 10% off. Bring a photo and your bank details to join.',null,null,null,'practice'),
  ('ai:ai-batch-07:754fadae163e','A2'::public.cefr_level,'reading','Which class is on Wednesdays?',array['boxing','swimming','dance','yoga']::text[],'C','''...dance on Wednesdays.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','FitLife Gym — New Year Offer! Join before 31st January and pay only £20 a month (normal price £30). Open 6 am – 10 pm every day. Free fitness classes: yoga on Mondays, dance on Wednesdays, boxing on Fridays. Students get a further 10% off. Bring a photo and your bank details to join.',null,null,null,'practice'),
  ('ai:ai-batch-07:69083d798bef','A2'::public.cefr_level,'reading','Who can get an extra discount?',array['children','people over 60','students','people who join in February']::text[],'C','''Students get a further 10% off.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','FitLife Gym — New Year Offer! Join before 31st January and pay only £20 a month (normal price £30). Open 6 am – 10 pm every day. Free fitness classes: yoga on Mondays, dance on Wednesdays, boxing on Fridays. Students get a further 10% off. Bring a photo and your bank details to join.',null,null,null,'practice'),
  ('ai:ai-batch-07:e836fc4a1fa1','A2'::public.cefr_level,'reading','What do you need to bring to join?',array['sports shoes','a photo and bank details','£30 in cash','a student card only']::text[],'B','''Bring a photo and your bank details to join.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','FitLife Gym — New Year Offer! Join before 31st January and pay only £20 a month (normal price £30). Open 6 am – 10 pm every day. Free fitness classes: yoga on Mondays, dance on Wednesdays, boxing on Fridays. Students get a further 10% off. Bring a photo and your bank details to join.',null,null,null,'practice'),
  ('ai:ai-batch-07:83343a411811','A2'::public.cefr_level,'reading','When did people start building Stonehenge?',array['about 500 years ago','about 5,000 years ago','200 years ago','a million years ago']::text[],'B','''People started building it about 5,000 years ago.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Stonehenge is a famous circle of large stones in the south of England. People started building it about 5,000 years ago. Some of the stones came from Wales, more than 200 kilometres away. Nobody knows exactly how people moved them or why they built it. Some experts think it was a kind of calendar, because on the longest day of the year the sun rises in line with the stones. Today more than a million people visit it every year.',null,null,null,'practice'),
  ('ai:ai-batch-07:e371d507cae9','A2'::public.cefr_level,'reading','Where did some of the stones come from?',array['Wales','the south of England','France','Scotland']::text[],'A','''Some of the stones came from Wales.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Stonehenge is a famous circle of large stones in the south of England. People started building it about 5,000 years ago. Some of the stones came from Wales, more than 200 kilometres away. Nobody knows exactly how people moved them or why they built it. Some experts think it was a kind of calendar, because on the longest day of the year the sun rises in line with the stones. Today more than a million people visit it every year.',null,null,null,'practice'),
  ('ai:ai-batch-07:b1130591143a','A2'::public.cefr_level,'reading','Why do some experts think Stonehenge was a calendar?',array['It has twelve stones.','People wrote dates on it.','It shows the months.','The sun rises in line with the stones on the longest day.']::text[],'D','''On the longest day of the year the sun rises in line with the stones.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Stonehenge is a famous circle of large stones in the south of England. People started building it about 5,000 years ago. Some of the stones came from Wales, more than 200 kilometres away. Nobody knows exactly how people moved them or why they built it. Some experts think it was a kind of calendar, because on the longest day of the year the sun rises in line with the stones. Today more than a million people visit it every year.',null,null,null,'practice'),
  ('ai:ai-batch-07:a88f9ac5a90b','A2'::public.cefr_level,'reading','What does the text say we don''t know?',array['how and why it was built','how many people visit','how old it is','where it is']::text[],'A','''Nobody knows exactly how people moved them or why they built it.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Stonehenge is a famous circle of large stones in the south of England. People started building it about 5,000 years ago. Some of the stones came from Wales, more than 200 kilometres away. Nobody knows exactly how people moved them or why they built it. Some experts think it was a kind of calendar, because on the longest day of the year the sun rises in line with the stones. Today more than a million people visit it every year.',null,null,null,'practice'),
  ('ai:ai-batch-07:2fc4ca29d360','A2'::public.cefr_level,'reading','What was wrong with the coffee machine?',array['It was the wrong colour.','It arrived late.','It was too expensive.','It didn''t work.']::text[],'D','''I tried to use the machine, but it didn''t work.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear Sir or Madam, Last week I bought a coffee machine from your online shop. When it arrived, I noticed that the box was damaged. I tried to use the machine, but it didn''t work. I would like to return it and get my money back. Could you tell me how to send it back? My order number is 45721. Yours faithfully, P. Ahmed',null,null,null,'practice'),
  ('ai:ai-batch-07:ae74c6f9fd88','A2'::public.cefr_level,'reading','What does P. Ahmed want?',array['to return it and get a refund','a new box','a discount','to buy another machine']::text[],'A','''I would like to return it and get my money back.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear Sir or Madam, Last week I bought a coffee machine from your online shop. When it arrived, I noticed that the box was damaged. I tried to use the machine, but it didn''t work. I would like to return it and get my money back. Could you tell me how to send it back? My order number is 45721. Yours faithfully, P. Ahmed',null,null,null,'practice'),
  ('ai:ai-batch-07:af187e454aa4','A2'::public.cefr_level,'reading','What did the writer notice when the parcel arrived?',array['The box was damaged.','The order number was wrong.','The machine was missing.','It was the wrong size.']::text[],'A','''I noticed that the box was damaged.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear Sir or Madam, Last week I bought a coffee machine from your online shop. When it arrived, I noticed that the box was damaged. I tried to use the machine, but it didn''t work. I would like to return it and get my money back. Could you tell me how to send it back? My order number is 45721. Yours faithfully, P. Ahmed',null,null,null,'practice'),
  ('ai:ai-batch-07:f24a9cecc27f','A2'::public.cefr_level,'reading','What information does the writer ask for?',array['a new order number','how to send it back','the price','the shop''s opening hours']::text[],'B','''Could you tell me how to send it back?''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear Sir or Madam, Last week I bought a coffee machine from your online shop. When it arrived, I noticed that the box was damaged. I tried to use the machine, but it didn''t work. I would like to return it and get my money back. Could you tell me how to send it back? My order number is 45721. Yours faithfully, P. Ahmed',null,null,null,'practice'),
  ('ai:ai-batch-07:afb1c6780f6d','A2'::public.cefr_level,'reading','Who showed the writer the office?',array['Raj','Ellie','the manager, Jane','a receptionist']::text[],'C','''My manager, Jane, showed me the office.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Monday: I started my new job today. My manager, Jane, showed me the office and introduced me to everyone. I had lunch with two colleagues, Raj and Ellie. The work was more difficult than I expected, but everyone was helpful. Tuesday: I arrived late because my train was delayed. I felt terrible, but Jane said it wasn''t a problem. In the afternoon I wrote my first report.',null,null,null,'practice'),
  ('ai:ai-batch-07:9a1082b40f01','A2'::public.cefr_level,'reading','How did the writer find the work on the first day?',array['boring','very easy','more difficult than expected','exactly as expected']::text[],'C','''The work was more difficult than I expected.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Monday: I started my new job today. My manager, Jane, showed me the office and introduced me to everyone. I had lunch with two colleagues, Raj and Ellie. The work was more difficult than I expected, but everyone was helpful. Tuesday: I arrived late because my train was delayed. I felt terrible, but Jane said it wasn''t a problem. In the afternoon I wrote my first report.',null,null,null,'practice'),
  ('ai:ai-batch-07:493256268745','A2'::public.cefr_level,'reading','Why was the writer late on Tuesday?',array['There was a lot of traffic.','The writer was ill.','The alarm didn''t ring.','The train was delayed.']::text[],'D','''I arrived late because my train was delayed.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Monday: I started my new job today. My manager, Jane, showed me the office and introduced me to everyone. I had lunch with two colleagues, Raj and Ellie. The work was more difficult than I expected, but everyone was helpful. Tuesday: I arrived late because my train was delayed. I felt terrible, but Jane said it wasn''t a problem. In the afternoon I wrote my first report.',null,null,null,'practice'),
  ('ai:ai-batch-07:7831a9a75a17','A2'::public.cefr_level,'reading','How did Jane react?',array['She sent the writer home.','She was angry.','She didn''t notice.','She said it wasn''t a problem.']::text[],'D','''Jane said it wasn''t a problem.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Monday: I started my new job today. My manager, Jane, showed me the office and introduced me to everyone. I had lunch with two colleagues, Raj and Ellie. The work was more difficult than I expected, but everyone was helpful. Tuesday: I arrived late because my train was delayed. I felt terrible, but Jane said it wasn''t a problem. In the afternoon I wrote my first report.',null,null,null,'practice'),
  ('ai:ai-batch-07:13450df6a084','A2'::public.cefr_level,'reading','How can you get to Skye without a boat?',array['by plane','on foot through a tunnel','by train','by car over a bridge']::text[],'D','''You can get there by car over a bridge.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Isle of Skye is an island off the west coast of Scotland. It is famous for its mountains, waterfalls and castles. You can get there by car over a bridge, so you don''t need to take a boat. The weather changes quickly, so visitors should bring warm clothes and waterproofs, even in summer. In August the island is very busy, so it is best to book accommodation early.',null,null,null,'practice'),
  ('ai:ai-batch-07:6747c1575225','A2'::public.cefr_level,'reading','Why should visitors bring waterproofs even in summer?',array['It always rains in summer.','The castles are wet.','There are many waterfalls.','The weather changes quickly.']::text[],'D','''The weather changes quickly, so visitors should bring warm clothes and waterproofs.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Isle of Skye is an island off the west coast of Scotland. It is famous for its mountains, waterfalls and castles. You can get there by car over a bridge, so you don''t need to take a boat. The weather changes quickly, so visitors should bring warm clothes and waterproofs, even in summer. In August the island is very busy, so it is best to book accommodation early.',null,null,null,'practice'),
  ('ai:ai-batch-07:4c998f3dc569','A2'::public.cefr_level,'reading','What advice does the text give about August?',array['Don''t visit in August.','Take a boat.','Book accommodation early.','Bring summer clothes only.']::text[],'C','''In August the island is very busy, so it is best to book accommodation early.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Isle of Skye is an island off the west coast of Scotland. It is famous for its mountains, waterfalls and castles. You can get there by car over a bridge, so you don''t need to take a boat. The weather changes quickly, so visitors should bring warm clothes and waterproofs, even in summer. In August the island is very busy, so it is best to book accommodation early.',null,null,null,'practice'),
  ('ai:ai-batch-07:f1de85405873','A2'::public.cefr_level,'reading','What is Skye famous for?',array['beaches and hot weather','big cities','mountains, waterfalls and castles','its bridge']::text[],'C','''It is famous for its mountains, waterfalls and castles.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Isle of Skye is an island off the west coast of Scotland. It is famous for its mountains, waterfalls and castles. You can get there by car over a bridge, so you don''t need to take a boat. The weather changes quickly, so visitors should bring warm clothes and waterproofs, even in summer. In August the island is very busy, so it is best to book accommodation early.',null,null,null,'practice'),
  ('ai:ai-batch-07:d31117cb21f2','A2'::public.cefr_level,'reading','How many pancakes does the recipe make?',array['300','2','100','8']::text[],'D','''Easy pancakes (makes 8).''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Easy pancakes (makes 8). You need: 100 g flour, 2 eggs, 300 ml milk, a little oil. First, put the flour in a bowl and add the eggs. Then slowly add the milk and mix well. Heat a little oil in a frying pan. Pour in some of the mixture and cook for one minute on each side. Serve with lemon and sugar.',null,null,null,'practice'),
  ('ai:ai-batch-07:1e1301d5ef65','A2'::public.cefr_level,'reading','What do you add to the flour first?',array['the milk','the oil','the eggs','lemon and sugar']::text[],'C','''Put the flour in a bowl and add the eggs.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Easy pancakes (makes 8). You need: 100 g flour, 2 eggs, 300 ml milk, a little oil. First, put the flour in a bowl and add the eggs. Then slowly add the milk and mix well. Heat a little oil in a frying pan. Pour in some of the mixture and cook for one minute on each side. Serve with lemon and sugar.',null,null,null,'practice'),
  ('ai:ai-batch-07:1c3b1f2d2996','A2'::public.cefr_level,'reading','How long do you cook each side?',array['five minutes','one minute','two minutes','until it''s black']::text[],'B','''Cook for one minute on each side.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Easy pancakes (makes 8). You need: 100 g flour, 2 eggs, 300 ml milk, a little oil. First, put the flour in a bowl and add the eggs. Then slowly add the milk and mix well. Heat a little oil in a frying pan. Pour in some of the mixture and cook for one minute on each side. Serve with lemon and sugar.',null,null,null,'practice'),
  ('ai:ai-batch-07:dbcda78a52a5','A2'::public.cefr_level,'reading','How should you add the milk?',array['slowly','before the flour','all at once','after cooking']::text[],'A','''Then slowly add the milk and mix well.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Easy pancakes (makes 8). You need: 100 g flour, 2 eggs, 300 ml milk, a little oil. First, put the flour in a bowl and add the eggs. Then slowly add the milk and mix well. Heat a little oil in a frying pan. Pour in some of the mixture and cook for one minute on each side. Serve with lemon and sugar.',null,null,null,'practice'),
  ('ai:ai-batch-07:ed013ecd0439','A2'::public.cefr_level,'reading','When does Grace volunteer?',array['once a month','every Saturday morning','on Sundays','every evening']::text[],'B','''Every Saturday morning, Grace volunteers at an animal shelter.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Every Saturday morning, Grace volunteers at an animal shelter near Cardiff. She walks the dogs, cleans the cages and helps visitors who want to adopt a pet. She started two years ago because she couldn''t have a dog in her flat. ''It''s the best part of my week,'' she says. ''The animals are so happy to see me.'' Last year Grace helped find homes for more than thirty dogs.',null,null,null,'practice'),
  ('ai:ai-batch-07:0d00698b67c8','A2'::public.cefr_level,'reading','Why did Grace start volunteering?',array['She wanted to be a vet.','Her friend asked her.','She couldn''t have a dog in her flat.','She needed money.']::text[],'C','''...because she couldn''t have a dog in her flat.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Every Saturday morning, Grace volunteers at an animal shelter near Cardiff. She walks the dogs, cleans the cages and helps visitors who want to adopt a pet. She started two years ago because she couldn''t have a dog in her flat. ''It''s the best part of my week,'' she says. ''The animals are so happy to see me.'' Last year Grace helped find homes for more than thirty dogs.',null,null,null,'practice'),
  ('ai:ai-batch-07:98e0f0d28427','A2'::public.cefr_level,'reading','Which job does Grace NOT do at the shelter?',array['feeding the cats','helping visitors','cleaning the cages','walking the dogs']::text[],'A','The text mentions walking dogs, cleaning cages and helping visitors.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Every Saturday morning, Grace volunteers at an animal shelter near Cardiff. She walks the dogs, cleans the cages and helps visitors who want to adopt a pet. She started two years ago because she couldn''t have a dog in her flat. ''It''s the best part of my week,'' she says. ''The animals are so happy to see me.'' Last year Grace helped find homes for more than thirty dogs.',null,null,null,'practice'),
  ('ai:ai-batch-07:956c42cbdc8f','A2'::public.cefr_level,'reading','What did Grace achieve last year?',array['opened a new shelter','adopted thirty dogs','became a manager','helped find homes for over thirty dogs']::text[],'D','''Last year Grace helped find homes for more than thirty dogs.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Every Saturday morning, Grace volunteers at an animal shelter near Cardiff. She walks the dogs, cleans the cages and helps visitors who want to adopt a pet. She started two years ago because she couldn''t have a dog in her flat. ''It''s the best part of my week,'' she says. ''The animals are so happy to see me.'' Last year Grace helped find homes for more than thirty dogs.',null,null,null,'practice'),
  ('ai:ai-batch-07:d6de38ec1079','A2'::public.cefr_level,'reading','Why will there be no trains between Bath and Bristol on Sunday?',array['engineering work','a strike','a holiday','bad weather']::text[],'A','''...because of engineering work.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear passengers, because of engineering work, there will be no trains between Bath and Bristol this Sunday. A bus service will replace the trains. Buses will leave from outside the main entrance every 20 minutes. Journeys will take about 30 minutes longer than usual. Tickets for the train are valid on the bus. We are sorry for any inconvenience.',null,null,null,'practice'),
  ('ai:ai-batch-07:b46196803979','A2'::public.cefr_level,'reading','Where do the replacement buses leave from?',array['outside the main entrance','the bus station','platform 1','Bristol city centre']::text[],'A','''Buses will leave from outside the main entrance.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear passengers, because of engineering work, there will be no trains between Bath and Bristol this Sunday. A bus service will replace the trains. Buses will leave from outside the main entrance every 20 minutes. Journeys will take about 30 minutes longer than usual. Tickets for the train are valid on the bus. We are sorry for any inconvenience.',null,null,null,'practice'),
  ('ai:ai-batch-07:e7719f6ac6fd','A2'::public.cefr_level,'reading','How much longer will the journey take?',array['no longer','about 20 minutes','about 30 minutes','about an hour']::text[],'C','''Journeys will take about 30 minutes longer than usual.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear passengers, because of engineering work, there will be no trains between Bath and Bristol this Sunday. A bus service will replace the trains. Buses will leave from outside the main entrance every 20 minutes. Journeys will take about 30 minutes longer than usual. Tickets for the train are valid on the bus. We are sorry for any inconvenience.',null,null,null,'practice'),
  ('ai:ai-batch-07:7bb6e4edbcfa','A2'::public.cefr_level,'reading','Can you use your train ticket on the bus?',array['Yes','Only return tickets','No, you need a new ticket','Only on Sunday morning']::text[],'A','''Tickets for the train are valid on the bus.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Dear passengers, because of engineering work, there will be no trains between Bath and Bristol this Sunday. A bus service will replace the trains. Buses will leave from outside the main entrance every 20 minutes. Journeys will take about 30 minutes longer than usual. Tickets for the train are valid on the bus. We are sorry for any inconvenience.',null,null,null,'practice'),
  ('ai:ai-batch-07:ec0a7444891e','A2'::public.cefr_level,'reading','How is Ruth different from Rachel?',array['Ruth is a vet.','Ruth is outgoing, but Rachel is quiet.','Ruth is quiet, but Rachel loves parties.','Ruth lives in Devon.']::text[],'B','''Ruth is outgoing... Rachel is quiet.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Ruth and Rachel are twins, but they are very different. Ruth is outgoing and loves parties, while Rachel is quiet and prefers reading at home. Ruth studied business and now works in a bank in London. Rachel became a vet and lives in a small village in Devon. They talk on the phone every evening and spend every Christmas together.',null,null,null,'practice'),
  ('ai:ai-batch-07:3ed5969fa529','A2'::public.cefr_level,'reading','What is Rachel''s job?',array['librarian','banker','teacher','vet']::text[],'D','''Rachel became a vet.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Ruth and Rachel are twins, but they are very different. Ruth is outgoing and loves parties, while Rachel is quiet and prefers reading at home. Ruth studied business and now works in a bank in London. Rachel became a vet and lives in a small village in Devon. They talk on the phone every evening and spend every Christmas together.',null,null,null,'practice'),
  ('ai:ai-batch-07:46cf9ef9f1f5','A2'::public.cefr_level,'reading','How often do the twins talk on the phone?',array['once a week','every evening','every Christmas','never']::text[],'B','''They talk on the phone every evening.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Ruth and Rachel are twins, but they are very different. Ruth is outgoing and loves parties, while Rachel is quiet and prefers reading at home. Ruth studied business and now works in a bank in London. Rachel became a vet and lives in a small village in Devon. They talk on the phone every evening and spend every Christmas together.',null,null,null,'practice'),
  ('ai:ai-batch-07:6c727611d5d1','A2'::public.cefr_level,'reading','Where does Ruth work?',array['in a bank in London','in a shop','at home','in a village in Devon']::text[],'A','''Ruth... now works in a bank in London.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Ruth and Rachel are twins, but they are very different. Ruth is outgoing and loves parties, while Rachel is quiet and prefers reading at home. Ruth studied business and now works in a bank in London. Rachel became a vet and lives in a small village in Devon. They talk on the phone every evening and spend every Christmas together.',null,null,null,'practice'),
  ('ai:ai-batch-07:a907c9a781e1','A2'::public.cefr_level,'reading','Where must dogs be on a lead?',array['in the café','near the children''s playground','everywhere in the park','on the cycle paths']::text[],'B','''Please keep dogs on a lead near the children''s playground.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Welcome to Greenfield Park. Please keep dogs on a lead near the children''s playground. Cycling is allowed only on the marked paths. Barbecues are not permitted. The café is open from 9 am to 5 pm in summer and from 10 am to 3 pm in winter. Free guided walks start at the main gate every Sunday at 11 am.',null,null,null,'practice'),
  ('ai:ai-batch-07:adb9dae19e28','A2'::public.cefr_level,'reading','What is NOT allowed in the park?',array['dogs','barbecues','cycling on marked paths','guided walks']::text[],'B','''Barbecues are not permitted.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Welcome to Greenfield Park. Please keep dogs on a lead near the children''s playground. Cycling is allowed only on the marked paths. Barbecues are not permitted. The café is open from 9 am to 5 pm in summer and from 10 am to 3 pm in winter. Free guided walks start at the main gate every Sunday at 11 am.',null,null,null,'practice'),
  ('ai:ai-batch-07:551a8ad8cc3f','A2'::public.cefr_level,'reading','When does the café close in winter?',array['9 am','10 am','5 pm','3 pm']::text[],'D','''...from 10 am to 3 pm in winter.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Welcome to Greenfield Park. Please keep dogs on a lead near the children''s playground. Cycling is allowed only on the marked paths. Barbecues are not permitted. The café is open from 9 am to 5 pm in summer and from 10 am to 3 pm in winter. Free guided walks start at the main gate every Sunday at 11 am.',null,null,null,'practice'),
  ('ai:ai-batch-07:9e702fa0446b','A2'::public.cefr_level,'reading','How much do the guided walks cost?',array['£3','£11','nothing','£5']::text[],'C','''Free guided walks...''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Welcome to Greenfield Park. Please keep dogs on a lead near the children''s playground. Cycling is allowed only on the marked paths. Barbecues are not permitted. The café is open from 9 am to 5 pm in summer and from 10 am to 3 pm in winter. Free guided walks start at the main gate every Sunday at 11 am.',null,null,null,'practice'),
  ('ai:ai-batch-07:666681a4f40c','A2'::public.cefr_level,'reading','Where was Alexander Graham Bell born?',array['in the United States','in Edinburgh','in London','in Canada']::text[],'B','''Bell was born in Edinburgh in 1847.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The first successful telephone call was made by Alexander Graham Bell in 1876. Bell was born in Edinburgh in 1847 and later moved to Canada and then to the United States. His mother and his wife were both deaf, and much of his work was about helping deaf people communicate. Today, more than five billion people around the world use a mobile phone.',null,null,null,'practice'),
  ('ai:ai-batch-07:07cfb2ffbde4','A2'::public.cefr_level,'reading','When was the first successful telephone call?',array['1847','1906','1876','1776']::text[],'C','''...made by Alexander Graham Bell in 1876.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The first successful telephone call was made by Alexander Graham Bell in 1876. Bell was born in Edinburgh in 1847 and later moved to Canada and then to the United States. His mother and his wife were both deaf, and much of his work was about helping deaf people communicate. Today, more than five billion people around the world use a mobile phone.',null,null,null,'practice'),
  ('ai:ai-batch-07:cde2d8e1fd9c','A2'::public.cefr_level,'reading','Why was much of Bell''s work about helping deaf people?',array['He was a doctor.','His mother and his wife were deaf.','He was deaf himself.','The government paid him.']::text[],'B','''His mother and his wife were both deaf.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The first successful telephone call was made by Alexander Graham Bell in 1876. Bell was born in Edinburgh in 1847 and later moved to Canada and then to the United States. His mother and his wife were both deaf, and much of his work was about helping deaf people communicate. Today, more than five billion people around the world use a mobile phone.',null,null,null,'practice'),
  ('ai:ai-batch-07:77affe1d466c','A2'::public.cefr_level,'reading','How many people use a mobile phone today, according to the text?',array['about one million','more than five billion','everyone in the world','five hundred million']::text[],'B','''...more than five billion people around the world use a mobile phone.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The first successful telephone call was made by Alexander Graham Bell in 1876. Bell was born in Edinburgh in 1847 and later moved to Canada and then to the United States. His mother and his wife were both deaf, and much of his work was about helping deaf people communicate. Today, more than five billion people around the world use a mobile phone.',null,null,null,'practice'),
  ('ai:ai-batch-07:0e4d7abfdf7c','A2'::public.cefr_level,'reading','When does the book club meet?',array['the first Thursday of every month','every Thursday','every week','the last Friday of the month']::text[],'A','''...meets on the first Thursday of every month.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Hilltop Book Club meets on the first Thursday of every month at 7 pm in the community centre. Each month we read one novel and then discuss it together over tea and biscuits. New members are always welcome. You don''t need to buy the books — the local library keeps copies for us. This month''s book is ''The Secret Garden''.',null,null,null,'practice'),
  ('ai:ai-batch-07:18099ba60585','A2'::public.cefr_level,'reading','Do members have to buy the books?',array['Yes, from the club.','No, the library keeps copies.','Only new members.','Yes, every month.']::text[],'B','''You don''t need to buy the books — the local library keeps copies.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Hilltop Book Club meets on the first Thursday of every month at 7 pm in the community centre. Each month we read one novel and then discuss it together over tea and biscuits. New members are always welcome. You don''t need to buy the books — the local library keeps copies for us. This month''s book is ''The Secret Garden''.',null,null,null,'practice'),
  ('ai:ai-batch-07:6203b0de01c5','A2'::public.cefr_level,'reading','What do members do at the meetings?',array['read aloud for an hour','sell books','discuss the book','write a book']::text[],'C','''...discuss it together over tea and biscuits.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Hilltop Book Club meets on the first Thursday of every month at 7 pm in the community centre. Each month we read one novel and then discuss it together over tea and biscuits. New members are always welcome. You don''t need to buy the books — the local library keeps copies for us. This month''s book is ''The Secret Garden''.',null,null,null,'practice'),
  ('ai:ai-batch-07:e1a20e4f7fdc','A2'::public.cefr_level,'reading','Where does the club meet?',array['at members'' homes','in the library','in a café','in the community centre']::text[],'D','''...at 7 pm in the community centre.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','The Hilltop Book Club meets on the first Thursday of every month at 7 pm in the community centre. Each month we read one novel and then discuss it together over tea and biscuits. New members are always welcome. You don''t need to buy the books — the local library keeps copies for us. This month''s book is ''The Secret Garden''.',null,null,null,'practice'),
  ('ai:ai-batch-07:59260c9847b3','A2'::public.cefr_level,'reading','What is the first piece of advice?',array['write down everything you spend for a month','ask for a pay rise','open a new bank account','stop buying coffee']::text[],'A','''First, write down everything you spend for a month.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Q: I want to save money but I always spend everything by the end of the month. What can I do? — A: First, write down everything you spend for a month. You''ll be surprised how much goes on coffee and snacks! Then decide on a small amount to save each week, even £5, and put it in a separate account as soon as you are paid. Finally, try cooking at home more often instead of buying lunch.',null,null,null,'practice'),
  ('ai:ai-batch-07:9d66cb9d71f7','A2'::public.cefr_level,'reading','When should you move money into savings?',array['when you have £100','once a year','at the end of the month','as soon as you are paid']::text[],'D','''...put it in a separate account as soon as you are paid.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Q: I want to save money but I always spend everything by the end of the month. What can I do? — A: First, write down everything you spend for a month. You''ll be surprised how much goes on coffee and snacks! Then decide on a small amount to save each week, even £5, and put it in a separate account as soon as you are paid. Finally, try cooking at home more often instead of buying lunch.',null,null,null,'practice'),
  ('ai:ai-batch-07:4dca880f4131','A2'::public.cefr_level,'reading','What might surprise the person?',array['how much they spend on coffee and snacks','how much they earn','how cheap food is','how much they save']::text[],'A','''You''ll be surprised how much goes on coffee and snacks!''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Q: I want to save money but I always spend everything by the end of the month. What can I do? — A: First, write down everything you spend for a month. You''ll be surprised how much goes on coffee and snacks! Then decide on a small amount to save each week, even £5, and put it in a separate account as soon as you are paid. Finally, try cooking at home more often instead of buying lunch.',null,null,null,'practice'),
  ('ai:ai-batch-07:b228e330e045','A2'::public.cefr_level,'reading','How did the writer''s class do overall?',array['They came second.','They came last.','They won.','They didn''t take part.']::text[],'A','''My class came second overall.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Our school sports day was last Friday. The weather was perfect — sunny but not too hot. There were running races, the long jump and a tug of war between the teachers and the students. The students won the tug of war for the first time in ten years! My class came second overall, just behind class 9C. After the events, parents sold cakes to raise money for new football shirts.',null,null,null,'practice'),
  ('ai:ai-batch-07:b4bdf3248485','A2'::public.cefr_level,'reading','What was special about the tug of war this year?',array['The students won for the first time in ten years.','It was cancelled.','The teachers won again.','Parents took part.']::text[],'A','''The students won the tug of war for the first time in ten years!''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Our school sports day was last Friday. The weather was perfect — sunny but not too hot. There were running races, the long jump and a tug of war between the teachers and the students. The students won the tug of war for the first time in ten years! My class came second overall, just behind class 9C. After the events, parents sold cakes to raise money for new football shirts.',null,null,null,'practice'),
  ('ai:ai-batch-07:45f3f9fe9446','A2'::public.cefr_level,'reading','Why did parents sell cakes?',array['to raise money for football shirts','for a school trip','to pay the teachers','to buy new books']::text[],'A','''...to raise money for new football shirts.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Our school sports day was last Friday. The weather was perfect — sunny but not too hot. There were running races, the long jump and a tug of war between the teachers and the students. The students won the tug of war for the first time in ten years! My class came second overall, just behind class 9C. After the events, parents sold cakes to raise money for new football shirts.',null,null,null,'practice'),
  ('ai:ai-batch-07:5c5867962f0d','A2'::public.cefr_level,'reading','What was the weather like on sports day?',array['sunny but not too hot','cold and wet','windy','very hot']::text[],'A','''The weather was perfect — sunny but not too hot.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-07','Our school sports day was last Friday. The weather was perfect — sunny but not too hot. There were running races, the long jump and a tug of war between the teachers and the students. The students won the tug of war for the first time in ten years! My class came second overall, just behind class 9C. After the events, parents sold cakes to raise money for new football shirts.',null,null,null,'practice'),
  ('ai:ai-batch-07:1ad47582899f','A2'::public.cefr_level,'grammar','I''m not sure, but I ___ go to the concert tonight.',array['may','must','have to','should to']::text[],'A','''May'' expresses possibility.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:12b9d0606bc4','A2'::public.cefr_level,'grammar','You ___ eat so much sugar. It''s bad for you.',array['don''t should','shouldn''t','haven''t','mustn''t to']::text[],'B','Advice not to do something: shouldn''t.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:eed5ebc517c5','A2'::public.cefr_level,'grammar','She has been learning English ___ she was six.',array['since','for','ago','from']::text[],'A','''Since'' + a past point.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:d4de6fb645fe','A2'::public.cefr_level,'grammar','This is the most beautiful beach I ___.',array['am seeing','ever saw','have never seen','have ever seen']::text[],'D','Superlative + present perfect with ''ever''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:49f3ea7e4df7','A2'::public.cefr_level,'grammar','I''ll lend you the book when I ___ it.',array['finish','will finish','am finish','finished']::text[],'A','After ''when'' about the future: present simple.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:161e25671951','A2'::public.cefr_level,'grammar','It ___ rain later, so take an umbrella just in case.',array['is','might','must','should to']::text[],'B','''Might'' = maybe.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:39e1fcf2b32d','A2'::public.cefr_level,'grammar','We were ___ tired that we went straight to bed.',array['too','very','so','such']::text[],'C','''So + adjective + that''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:eeec06f88a7b','A2'::public.cefr_level,'grammar','It was ___ a lovely day that we went to the beach.',array['such','very','so','too']::text[],'A','''Such a + adjective + noun''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:34cae3657b00','A2'::public.cefr_level,'grammar','I''ve been to Paris, but I ___ been to Rome.',array['didn''t','haven''t','hasn''t','wasn''t']::text[],'B','Present perfect negative: haven''t been.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:38bad00d80b0','A2'::public.cefr_level,'grammar','She speaks English ___ than her brother.',array['more good','best','gooder','better']::text[],'D','The comparative of ''well'' is ''better''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:4c117bde9904','A2'::public.cefr_level,'grammar','___ is a good way to relax.',array['To swimming','Swim','Swims','Swimming']::text[],'D','An -ing form can be the subject of a sentence.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:5ff78adedfea','A2'::public.cefr_level,'grammar','I promise I ___ tell anyone.',array['am not','didn''t','don''t','won''t']::text[],'D','Promises use will/won''t.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:c89a88097def','A2'::public.cefr_level,'grammar','Neither of us ___ the answer.',array['know to','knowing','knowed','knew']::text[],'D','Past simple of ''know'': knew.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:28c11d9f0820','A2'::public.cefr_level,'vocabulary','I''d like to ___ some money from the cash machine.',array['get off','put out','take out','take off']::text[],'C','You take out (withdraw) money.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:a7e1aff4a6f5','A2'::public.cefr_level,'vocabulary','She ___ her driving test last week. Now she can drive alone.',array['passed','pass','passing','past']::text[],'A','You pass a test.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
