  ('ai:ai-batch-07:371e84dd2329','A2'::public.cefr_level,'vocabulary','We''re going ___ for a meal tonight.',array['away','out','outside','off']::text[],'B','''Go out for a meal'' = eat at a restaurant.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:a8cbff3684be','A2'::public.cefr_level,'vocabulary','Could you ___ the radio down? It''s too loud.',array['turn','make','take','put']::text[],'A','''Turn down'' = make quieter.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
