  ('ai:ai-batch-07:0b57123d8595','A2'::public.cefr_level,'vocabulary','I''ve got a ___ for the concert. Do you want to come?',array['spare ticket','spare tickets','free ticket off','extra seat up']::text[],'A','A spare ticket is one you don''t need.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:027ec09f4c48','A2'::public.cefr_level,'vocabulary','He ___ his arm playing rugby.',array['break','broken','broke','brake']::text[],'C','Past of ''break'': broke.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
