  ('ai:ai-batch-07:777fd8be3c63','A2'::public.cefr_level,'vocabulary','There''s a ___ outside. Let''s go for a walk in the sun.',array['lovely sun day','love day','lovely weather day','lovely day']::text[],'D','''It''s a lovely day'' describes nice weather.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:89dce63b86eb','A2'::public.cefr_level,'vocabulary','He''s very good ___ cooking.',array['for','in','on','at']::text[],'D','''Good at'' something.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
  ('ai:ai-batch-07:4c365d7ae9e5','A2'::public.cefr_level,'vocabulary','I''m sorry ___ being late.',array['about to','at','for','of']::text[],'C','''Sorry for'' + -ing.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
