  ('ai:ai-batch-07:194fe6179910','A2'::public.cefr_level,'vocabulary','The train was ___, so we couldn''t find seats.',array['crowd','empty','quiet','crowded']::text[],'D','Crowded = full of people.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-07',null,null,null,null,'practice'),
